function validate([grid, k]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 30) return 'grid has 1 to 30 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 30) return 'Each row has 1 to 30 numbers.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (!row.every(v => Number.isInteger(v) && v >= -100000 && v <= 100000)) return 'Numbers are integers between -10^5 and 10^5.';
  }
  if (!Number.isInteger(k) || k < 1 || k > Math.min(grid.length, n)) return 'k is between 1 and min(m, n).';
  return null;
}

