function minAbsDiff(grid, k) {
  const m = grid.length;
  const n = grid[0].length;
  const ans = [];
  for (let i = 0; i + k <= m; i++) {
    const row = [];
    for (let j = 0; j + k <= n; j++) {
      const values = [];
      for (let x = i; x < i + k; x++) {
        for (let y = j; y < j + k; y++) {
          values.push(grid[x][y]);
        }
      }
      values.sort((a, b) => a - b);
      let best = Infinity;
      for (let t = 1; t < values.length; t++) {
        if (values[t] !== values[t - 1]) {
          best = Math.min(best, values[t] - values[t - 1]);
        }
      }
      row.push(best === Infinity ? 0 : best);
    }
    ans.push(row);
  }
  return ans;
}

