function minAbsDiff(grid, k) {
  // Compare every pair of cells inside every block directly, ignoring pairs with equal numbers.
  const result = [];
  for (let top = 0; top <= grid.length - k; top++) {
    const line = [];
    for (let left = 0; left <= grid[0].length - k; left++) {
      const cells = [];
      for (let r = top; r < top + k; r++) for (let c = left; c < left + k; c++) cells.push(grid[r][c]);
      let smallest = 0;
      for (let p = 0; p < cells.length; p++) {
        for (let q = p + 1; q < cells.length; q++) {
          const gap = Math.abs(cells[p] - cells[q]);
          if (gap > 0 && (smallest === 0 || gap < smallest)) smallest = gap;
        }
      }
      line.push(smallest);
    }
    result.push(line);
  }
  return result;
}

