function generate(rand, size) {
  const pick = (limit) => Math.floor(rand() * limit);
  const m = size === 'large' ? 25 + pick(6) : 1 + pick(5);
  const n = size === 'large' ? 25 + pick(6) : 1 + pick(5);
  const k = 1 + pick(Math.min(m, n));
  // A narrow range repeats numbers (0 makes every cell equal); a wide one reaches the limits.
  const span = rand() < 0.4 ? pick(4) : rand() < 0.5 ? 50 : 100000;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => pick(2 * span + 1) - span));
  return [grid, k];
}
